		this.sendCommand("STOP " + channel, cb);
	};

	// ---
	// ccg.clear
	// ---
	// Clears a channel or layer
	//
	// [CLEAR](http://casparcg.com/wiki/CasparCG_2.0_AMCP_Protocol#CLEAR)
	ccg.prototype.clear = function (channel, cb) {
		this.sendCommand("CLEAR " + channel, cb);
	};

